import { LLMTag } from './llm-tags'
import type { Block } from './types'

export const blockIsInteractive = (block: Block) => {
	const isSummaryBlock =
		block.type === 'tag' && block.args?.uiType === 'summary'
	return (
		(block.type === 'tag' &&
			[
				LLMTag.CHOICES,
				LLMTag.INTEGRATION_SELECTION,
				LLMTag.MODULE_SELECTION,
				LLMTag.SUGGEST_ENVIRONMENT_VARIABLES,
				LLMTag.CONTINUE
			].includes(block.tag)) ||
		isSummaryBlock
	)
}
